package org.eclipse.ui.texteditor;

import org.eclipse.core.runtime.IProgressMonitor;
import org.eclipse.swt.widgets.Shell;
import org.eclipse.ui.IEditorInput;
import org.eclipse.ui.IWorkbenchSite;
import org.eclipse.ui.PlatformUI;
import org.eclipse.ui.IWorkbench;
import org.eclipse.ui.IModalDialogShellProvider;

interface IDocumentProvider {}

class PlatformUI {
    public static IWorkbench getWorkbench() {
        return new IWorkbench() {
            @Override
            public IModalDialogShellProvider getModalDialogShellProvider() {
                return new IModalDialogShellProvider() {
                    @Override
                    public Shell getShell() {
                        return new Shell();
                    }
                };
            }
        };
    }
}

interface IWorkbench {
    IModalDialogShellProvider getModalDialogShellProvider();
}

interface IModalDialogShellProvider {
    Shell getShell();
}

class WorkbenchPart {
    protected IWorkbenchSite getSite() {
        return new IWorkbenchSite() {
            @Override
            public Shell getShell() {
                return new Shell();
            }
        };
    }
}

public class AbstractDecoratedTextEditor extends WorkbenchPart {
    public IEditorInput getEditorInput() { return null; }
    public IDocumentProvider getDocumentProvider() { return null; }

    protected void performSaveAs(IProgressMonitor progressMonitor) {
        Shell shell= org.eclipse.ui.PlatformUI.getWorkbench().getModalDialogShellProvider().getShell();
        final IEditorInput input= getEditorInput();
    }
}

